# Kirby's Adventure (NES): the names this project gives to the program's
# routines, tables and variables, and what code discovery cannot recover by
# itself.
#
# The cartridge is an MMC3 board: 64 banks of 8 KiB of PRG ROM, the game in
# PRG mode 0 (bank 62 fixed at $C000, bank 63 at $E000, others switched in
# at $8000 and $A000), 8 KiB of battery-backed RAM at $6000, and 256 KiB of
# CHR ROM in 1 and 2 KiB banks. See src/image/rom.mbt for the syntax.

rom 1250a80faf865aa5ee5585ad7639e5ef2b3fa541554effda5fad2cc5dc2acef5 524288 262144 ; Kirby's Adventure (USA)
exact   ; the machine's stack, byte for byte (as the reference interpreter has it)

# The banks the game wants at $8000 and $A000, which it switches from
shadow $8000 $0048
shadow $a000 $0049

# The IRQ vector points to RAM, where the game writes the IRQ's code: what
# it writes to the PPU's mask (or the mapper), and where it goes
ram $0029 48 a9 .. 8d 00 e0 8d .. .. 4c .. ..

routine $d805 far_call          ; jsr far_call, then the routine's address and bank
inline $d805 3
# The window each bank runs in (from the game's switches, far calls and a
# recording)
bank 18 bank18 $8000
bank 19 bank19 $a000
bank 20 bank20 $a000
bank 21 bank21 $a000
bank 22 bank22 $a000
bank 23 bank23 $a000
bank 24 bank24 $a000
bank 29 bank29 $8000
bank 33 bank33 $8000
bank 34 bank34 $8000
bank 35 bank35 $a000
bank 36 bank36 $a000
bank 38 bank38 $a000
bank 40 bank40 $a000
bank 45 bank45 $a000
bank 46 bank46 $a000
bank 49 bank49 $8000
bank 52 bank52 $a000
bank 54 bank54 $a000
bank 55 bank55 $8000
bank 56 bank56 $a000
bank 57 bank57 $8000
bank 60 bank60 $a000
bank 61 bank61 $a000

# Calls through a pointer: the far call (jsr far_call, then the routine's
# address and bank), and jumps through $6038 and the IRQ's, to where the
# game goes (in the bank it maps there)
