# By hand
routine $c0be pointer_after_call ; jsr, then the address of what it reads
inline $c0be 2
trap 61:$b217                      ; lda $b217,y / bne: the table's bytes are not zero
trap 19:$a3a7     ; the table bytes after a branch the loaded value always takes
code 44:$ab1a pointers_44_ab1a 2 high $ab1c
jump 33:$9a91 33:$9b82             ; a script's routine (bank 25 sets it)

# Collision with slopes: by the tile's shape, routines the game returns
# through (lda high,y / pha / lda low,y / pha / rts)
code $f16a slope_moves_f16a 12 rts high $f176
code $f1b1 slope_moves_f1b1 12 rts high $f1bd
code $f205 slope_moves_f205 12 rts high $f211
code $f261 slope_moves_f261 12 rts high $f26d
